UPDATE workflow_run_event_cursor
SET terminal_event_type = #{terminalEventType}, terminal_sequence = next_sequence,
    next_sequence = next_sequence + 1, revision = revision + 1
WHERE tenant_id = #{tenantId} AND user_id = #{userId} AND run_id = #{runId}
  AND trace_id = #{traceId} AND revision = #{expectedRevision}
  AND terminal_event_type IS NULL AND deleted = 0
